def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    opponent_x, opponent_y = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    scores = observation['scores']
    path = observation['self_path']

    def safe_move(dx, dy):
        nx, ny = x + dx, y + dy
        return (0 <= nx < width and 0 <= ny < height
                and (nx, ny) not in obstacles)

    # Basic heuristics: prioritize resources, then move toward opponent
    # If resource nearby, go for it
    for rx, ry in resources:
        if abs(rx - x) + abs(ry - y) == 1:
            dx, dy = rx - x, ry - y
            if safe_move(dx, dy):
                return [dx, dy]
    # Move towards opponent if no immediate resource
    dx, dy = 0, 0
    if opponent_x > x:
        dx = 1
    elif opponent_x < x:
        dx = -1
    if opponent_y > y:
        dy = 1
    elif opponent_y < y:
        dy = -1
    # Try to move horizontally, then vertically if blocked
    if safe_move(dx, 0):
        return [dx, 0]
    if safe_move(0, dy):
        return [0, dy]
    # Try other directions
    for ddx, ddy in [(-1,0), (1,0), (0,-1), (0,1)]:
        if safe_move(ddx, ddy):
            return [ddx, ddy]
    # No move possible, stay
    return [0, 0]
